export const ENGLISH_BATCH = [
  // ── Language Techniques ──────────────────────────────────────────────────
  { id:'eng_065', q:'Which technique does the phrase "the cruel, cold wind clawed at my coat" primarily use?', opts:['Simile','Alliteration','Hyperbole','Onomatopoeia'], ans:1, topic:'Language Techniques', hint:'Notice the repeated "cl" consonant sound at the start of "cold", "clawed" and "coat". Repeated consonants = alliteration.', difficulty:1, tags:[] },
  { id:'eng_066', q:'In the sentence "The sun smiled down on the village," what technique is used?', opts:['Pathetic fallacy','Personification','Metaphor','Simile'], ans:1, topic:'Language Techniques', hint:'Giving a non-human thing (the sun) a human action (smiling) is personification. Pathetic fallacy is when weather reflects mood; this is just attribution of human behaviour.', difficulty:1, tags:[] },
  { id:'eng_067', q:'"Her eyes were two dark pools of sorrow." This is an example of:', opts:['Simile','Onomatopoeia','Metaphor','Alliteration'], ans:2, topic:'Language Techniques', hint:'A metaphor makes a direct comparison without "like" or "as". Here eyes ARE pools — no comparison word used.', difficulty:1, tags:[] },
  { id:'eng_068', q:'Which term describes language that appeals to the senses of sight, sound, smell, taste, or touch?', opts:['Emotive language','Imagery','Hyperbole','Juxtaposition'], ans:1, topic:'Language Techniques', hint:'Imagery creates sensory pictures in the reader\'s mind. Emotive language provokes emotion; hyperbole exaggerates; juxtaposition places contrasting ideas together.', difficulty:1, tags:[] },
  { id:'eng_069', q:'"I\'ve told you a million times!" — what technique does this use?', opts:['Litotes','Euphemism','Hyperbole','Oxymoron'], ans:2, topic:'Language Techniques', hint:'Deliberate exaggeration for effect is hyperbole. A million is obviously not literal.', difficulty:1, tags:[] },
  { id:'eng_070', q:'The technique of "pathetic fallacy" involves:', opts:['Attributing emotions to weather or nature to reflect human feelings','Using incorrect logic to mislead readers','Describing characters using animals as comparisons','Repeating a key phrase at the start of sentences'], ans:0, topic:'Language Techniques', hint:'Coined by John Ruskin, pathetic fallacy is when the natural environment mirrors or foreshadows a character\'s emotional state — e.g. stormy weather during conflict.', difficulty:2, tags:[] },
  { id:'eng_071', q:'Which device is used in: "Ask not what your country can do for you — ask what you can do for your country"?', opts:['Anaphora','Chiasmus','Epistrophe','Asyndeton'], ans:1, topic:'Language Techniques', hint:'Chiasmus reverses the grammatical structure of two clauses: "country / you" becomes "you / country". Anaphora repeats the start; epistrophe repeats the end.', difficulty:3, tags:[] },
  { id:'eng_072', q:'In the extract "The children laughed. The children danced. The children sang," what technique is used?', opts:['Anaphora','Epistrophe','Polysyndeton','Bathos'], ans:0, topic:'Language Techniques', hint:'Anaphora is the repetition of a word/phrase at the beginning of successive clauses ("The children..."). Epistrophe repeats at the end.', difficulty:2, tags:[] },
  { id:'eng_073', q:'What effect does a writer typically achieve through the use of short, simple sentences?', opts:['Creates a sense of luxury and grandeur','Slows the pace and encourages reflection','Creates tension, urgency or emphasis','Adds complexity and detail to description'], ans:2, topic:'Language Techniques', hint:'Short sentences punch hard. They speed up pace, create drama, and isolate an idea for emphasis. Long complex sentences slow pace; short ones accelerate it.', difficulty:2, tags:[] },
  { id:'eng_074', q:'"The silence screamed" is an example of:', opts:['Simile','Oxymoron','Irony','Paradox'], ans:1, topic:'Language Techniques', hint:'An oxymoron places two contradictory terms together ("silence" and "screamed" are opposites). A paradox is a broader statement that seems contradictory but contains truth.', difficulty:2, tags:[] },

  // ── Reading Comprehension ────────────────────────────────────────────────
  { id:'eng_075', q:'When a question asks you to "infer," what does it expect you to do?', opts:['Quote directly from the text','Explain the meaning of a word','Work out something implied but not directly stated','Summarise the whole passage'], ans:2, topic:'Reading Comprehension', hint:'Inference is reading between the lines — using clues in the text to reach a conclusion the writer implies but does not state explicitly.', difficulty:1, tags:[] },
  { id:'eng_076', q:'A student summarises a text but includes their personal opinion. This is a problem because:', opts:['The summary is too short','Summaries should not contain opinions not supported by the text','Personal opinions always contain factual errors','The student should have used quotations'], ans:1, topic:'Reading Comprehension', hint:'Summaries report what the text says. Adding unsupported personal opinions goes beyond what the text states and misrepresents it.', difficulty:2, tags:[] },
  { id:'eng_077', q:'What is the purpose of a "topic sentence" in a paragraph?', opts:['To provide evidence for the main argument','To introduce the main idea of the paragraph','To conclude the writer\'s argument','To define key vocabulary'], ans:1, topic:'Reading Comprehension', hint:'The topic sentence states the main point of the paragraph, orienting the reader for what follows. Evidence, analysis and conclusions come afterwards.', difficulty:1, tags:[] },
  { id:'eng_078', q:'Which reading skill involves distinguishing between what is fact and what is opinion?', opts:['Inference','Evaluation','Synthesis','Analysis'], ans:1, topic:'Reading Comprehension', hint:'Evaluation involves making judgements about the text, including whether statements are fact (can be verified) or opinion (a personal view).', difficulty:2, tags:[] },
  { id:'eng_079', q:'In a non-fiction text, a writer states: "Studies suggest chocolate may reduce stress." What is this an example of?', opts:['Definite fact','Biased opinion','Tentative language / hedging','Rhetorical question'], ans:2, topic:'Reading Comprehension', hint:'"Studies suggest" and "may" are hedging words that indicate uncertainty. Writers use tentative language to avoid claiming certainty they don\'t have.', difficulty:2, tags:[] },
  { id:'eng_080', q:'Which of the following best describes "synthesising" information from two texts?', opts:['Copying key quotes from both texts','Identifying similarities and differences, then combining insights','Focusing only on the text you prefer','Writing a summary of one text then the other'], ans:1, topic:'Reading Comprehension', hint:'Synthesis means bringing together information from multiple sources to form a new, unified understanding — not just listing each text separately.', difficulty:2, tags:[] },
  { id:'eng_081', q:'A writer who uses the second person ("you") is most likely trying to:', opts:['Distance themselves from the argument','Create a formal academic register','Directly address and involve the reader','Express uncertainty about their claims'], ans:2, topic:'Reading Comprehension', hint:'"You" directly implicates the reader, making them feel personally involved or addressed. This is a technique common in persuasive and advisory writing.', difficulty:2, tags:[] },
  { id:'eng_082', q:'What does "implicit" meaning refer to in a text?', opts:['Meaning stated clearly and directly','Meaning that is hidden, suggested or hinted at','Meaning that is factually incorrect','Meaning added by the reader\'s imagination'], ans:1, topic:'Reading Comprehension', hint:'Implicit = implied, not stated. Explicit = stated directly. Identifying implicit meaning requires inference.', difficulty:1, tags:[] },
  { id:'eng_083', q:'A news article describes a politician\'s decision as "controversial." This word choice suggests the writer views the decision as:', opts:['Clearly positive','Widely praised','Causing disagreement or debate','Illegal and corrupt'], ans:2, topic:'Reading Comprehension', hint:'"Controversial" means causing disagreement — it is a neutral-to-negative connotation word that signals the writer acknowledges public division without stating a personal view.', difficulty:2, tags:[] },
  { id:'eng_084', q:'Which feature distinguishes a broadsheet newspaper article from a tabloid article?', opts:['Broadsheets use more emotive language and shorter sentences','Broadsheets typically use formal language and more analytical content','Tabloids are always more accurate','Broadsheets never use images'], ans:1, topic:'Reading Comprehension', hint:'Broadsheets (e.g. The Guardian, The Times) traditionally use formal register, longer sentences, and analysis. Tabloids (e.g. The Sun) use accessible language and emotive headlines.', difficulty:2, tags:[] },

  // ── Literature – Shakespeare ─────────────────────────────────────────────
  { id:'eng_085', q:'In "Macbeth," what is the significance of Lady Macbeth saying "Out, damned spot"?', opts:['She is cleaning her house','She is hallucinating blood she cannot wash away, symbolising guilt','She is ordering Macbeth to stab the king','She has been physically wounded in battle'], ans:1, topic:'Literature (Shakespeare)', hint:'Lady Macbeth sleepwalks and imagines blood on her hands she cannot clean. This represents her overwhelming guilt for Duncan\'s murder — ironic as she earlier claimed "a little water clears us of this deed."', difficulty:2, tags:[] },
  { id:'eng_086', q:'In "Romeo and Juliet," what is the theme of "star-crossed lovers" primarily concerned with?', opts:['The lovers\' dislike of astrology','Fate and inevitability overriding free will','The influence of the planets on weather','A feud about astronomical observation'], ans:1, topic:'Literature (Shakespeare)', hint:'"Star-crossed" means opposed by the stars (fate). The prologue establishes that the lovers are doomed from the start, raising the theme of fate vs. free will throughout the play.', difficulty:1, tags:[] },
  { id:'eng_087', q:'In "A Midsummer Night\'s Dream," Oberon and Titania\'s quarrel is significant because:', opts:['It reveals Oberon is secretly villainous','Their supernatural conflict causes disorder in the natural world','It shows fairies have no power over mortals','Titania is ultimately shown to be right'], ans:1, topic:'Literature (Shakespeare)', hint:'Shakespeare links the supernatural and natural worlds — the fairy king and queen\'s discord causes "the seasons alter" and floods on earth, showing the order of nature mirrors the order of the fairy realm.', difficulty:2, tags:[] },
  { id:'eng_088', q:'In "Macbeth," which theme do the three witches most directly embody?', opts:['Love and loyalty','The supernatural and ambiguity of fate','Justice and punishment','Honour in battle'], ans:1, topic:'Literature (Shakespeare)', hint:'The witches represent the supernatural and raise questions about whether fate is predetermined. Their prophecies are ambiguous — they seem to both predict and cause events, blurring free will.', difficulty:1, tags:[] },
  { id:'eng_089', q:'The soliloquy "To be, or not to be" in "Hamlet" primarily explores:', opts:['Hamlet\'s love for Ophelia','Whether Hamlet should kill Claudius immediately','The question of whether life is worth living in the face of suffering','Hamlet\'s fear of being caught spying'], ans:2, topic:'Literature (Shakespeare)', hint:'This soliloquy is Hamlet\'s meditation on existence, suffering, and the unknown afterlife. The "undiscovered country" is death — he wonders if enduring life\'s pain is preferable to the unknown of death.', difficulty:2, tags:[] },
  { id:'eng_090', q:'In "The Merchant of Venice," what does Shylock\'s bond — a pound of flesh — most likely symbolise?', opts:['The importance of mercy over the law','Shylock\'s wealth and business acumen','The justice of trade laws in Venice','Antonio\'s physical cowardice'], ans:0, topic:'Literature (Shakespeare)', hint:'The "pound of flesh" contract is used to explore mercy vs strict justice. Portia\'s speech ("The quality of mercy is not strained") argues mercy should temper the law — which Shylock insists on literally.', difficulty:3, tags:[] },
  { id:'eng_091', q:'In "Macbeth," the recurring motif of blood primarily represents:', opts:['Scotland\'s military victories','Guilt, violence, and the consequences of ambition','The health of the king','Fertility of the land'], ans:1, topic:'Literature (Shakespeare)', hint:'Blood appears throughout — from the witches\' cauldron to Banquo\'s ghost and Lady Macbeth\'s hands. It is a visual symbol of guilt, murder, and the terrible consequences of unchecked ambition.', difficulty:1, tags:[] },
  { id:'eng_092', q:'What is the dramatic function of the Nurse in "Romeo and Juliet"?', opts:['She is the play\'s primary villain','She provides comic relief and acts as a go-between for the lovers','She represents the Montague family\'s values','She foreshadows the tragic ending through prophecy'], ans:1, topic:'Literature (Shakespeare)', hint:'The Nurse lightens the tone with her bawdy humour and serves as a confidante and messenger for Juliet. Her eventual betrayal (advising Juliet to marry Paris) marks a turning point.', difficulty:2, tags:[] },
  { id:'eng_093', q:'In "Othello," Iago\'s primary motivation for his scheming is most debated as:', opts:['Genuine love for Desdemona','Racism alone','A complex mix of jealousy, resentment, and desire for power','Simple greed for Othello\'s gold'], ans:2, topic:'Literature (Shakespeare)', hint:'Iago claims Cassio took his promotion, hints at jealousy over Emilia, and seems to enjoy manipulation itself. Critics debate whether he is purely evil ("motiveless malignity") or has legitimate grievances.', difficulty:3, tags:[] },
  { id:'eng_094', q:'Which technique does Shakespeare frequently use to allow characters to speak directly to the audience without other characters hearing?', opts:['Soliloquy','Aside','Monologue','Dramatic irony'], ans:1, topic:'Literature (Shakespeare)', hint:'An aside is a brief comment spoken to the audience, not heard by other characters on stage. A soliloquy is a longer speech when alone. Both create intimacy but asides occur mid-scene.', difficulty:2, tags:[] },

  // ── Poetry – Power & Conflict ────────────────────────────────────────────
  { id:'eng_095', q:'In Wilfred Owen\'s "Dulce et Decorum Est," what is the meaning of the Latin title?', opts:['It is sweet and fitting to die for your country','War is cruel and wasteful','Soldiers deserve medals for bravery','Death comes quickly in battle'], ans:0, topic:'Poetry (Power & Conflict)', hint:'"Dulce et decorum est pro patria mori" — "It is sweet and fitting to die for one\'s country" (Horace). Owen uses it ironically, calling it "the old Lie" after depicting the horror of a gas attack.', difficulty:1, tags:[] },
  { id:'eng_096', q:'In "Ozymandias" by Shelley, what is the central irony of the poem?', opts:['The statue is perfectly preserved after thousands of years','A powerful ruler\'s monument lies broken and forgotten in the desert','The sculptor deliberately broke the statue','Ozymandias is still alive'], ans:1, topic:'Poetry (Power & Conflict)', hint:'The "colossal wreck" of the statue in an empty desert ironically contradicts the boast "Look on my works, ye Mighty, and despair!" — showing that human power and ego ultimately decay.', difficulty:1, tags:[] },
  { id:'eng_097', q:'What poetic form does Carol Ann Duffy use in "War Photographer" to reflect a photographer\'s structured yet difficult work?', opts:['Free verse with no structure','A sonnet','Four regular stanzas suggesting order imposed on chaos','A ballad with a refrain'], ans:2, topic:'Poetry (Power & Conflict)', hint:'The four regular six-line stanzas create a sense of controlled, methodical process — mirroring how the photographer imposes order (developing film) on the chaos of war.', difficulty:2, tags:[] },
  { id:'eng_098', q:'In "My Last Duchess" by Browning, what does the Duke\'s use of a dramatic monologue reveal about his character?', opts:['He is humble and remorseful about his wife\'s death','He is controlling, possessive, and likely responsible for her death','He is a kind patron of the arts','He is grieving sincerely for the Duchess'], ans:1, topic:'Poetry (Power & Conflict)', hint:'The dramatic monologue lets Browning reveal the Duke\'s character through what he says and doesn\'t say. His casual reference to "giving commands" that stopped her smiles hints chillingly at her murder.', difficulty:2, tags:[] },
  { id:'eng_099', q:'In Seamus Heaney\'s "Storm on the Island," the island community prepares for a storm. What does the storm metaphorically represent?', opts:['A romantic adventure','The violence and uncertainty of the Troubles in Northern Ireland','The beauty of nature','The prosperity of island life'], ans:1, topic:'Poetry (Power & Conflict)', hint:'Heaney (a Northern Irish poet) writes about being "bombarded by the empty air" — the unseen, unpredictable force mirrors the violence of the Troubles. Preparation for storm = preparation for conflict.', difficulty:3, tags:[] },
  { id:'eng_100', q:'In "Charge of the Light Brigade" by Tennyson, the line "Into the valley of Death / Rode the six hundred" primarily uses which technique?', opts:['Simile comparing death to a valley','Allusion to the 23rd Psalm, linking sacrifice to religious duty','Onomatopoeia to suggest the sound of cannons','Irony to mock the soldiers\' bravery'], ans:1, topic:'Poetry (Power & Conflict)', hint:'"Valley of the shadow of Death" echoes Psalm 23. Tennyson elevates the soldiers\' sacrifice through biblical allusion — giving their deaths religious and heroic weight, even as he acknowledges the blunder.', difficulty:3, tags:[] },
  { id:'eng_101', q:'Which poetic technique involves attributing emotions or characteristics to a non-human entity in a poem?', opts:['Pathetic fallacy','Sibilance','Enjambment','Caesura'], ans:0, topic:'Poetry (Power & Conflict)', hint:'Pathetic fallacy (a form of personification) gives human emotions to nature. In war poetry it is often used — e.g. a "bitter" wind — to reflect soldiers\' suffering or desolation.', difficulty:1, tags:[] },
  { id:'eng_102', q:'In "Exposure" by Wilfred Owen, the soldiers\' greatest enemy is presented as:', opts:['German soldiers in the trenches opposite','The indifference of the government','The freezing, relentless weather — nature itself','The gas attacks at night'], ans:2, topic:'Poetry (Power & Conflict)', hint:'Exposure\'s title refers to exposure to the cold. The poem barely mentions enemy soldiers — Owen\'s focus is on the wind, sleet and snow that kill the men through cold, boredom, and despair.', difficulty:2, tags:[] },
  { id:'eng_103', q:'In Tennyson\'s "The Prelude" extract, what does the young Wordsworth\'s theft of a boat and subsequent experience suggest about nature?', opts:['Nature is entirely benevolent and nurturing','Nature has a moral, even punishing power that shapes the mind','Nature is indifferent to human beings','Nature is only beautiful when tamed'], ans:1, topic:'Poetry (Power & Conflict)', hint:'After stealing the boat, a huge peak seems to "stride after" him. Wordsworth portrays nature as a moral educator — the guilt and awe he feels shape his moral conscience ("Wisdom and Spirit of Nature").', difficulty:3, tags:[] },
  { id:'eng_104', q:'What is the effect of using enjambment in poetry?', opts:['Creates a pause or break mid-line','Allows a line to continue into the next without a pause, creating flow or unease','Signals the end of a stanza or idea','Repeats the first word of successive lines'], ans:1, topic:'Poetry (Power & Conflict)', hint:'Enjambment (from French "to straddle") runs a phrase across line breaks without punctuation. This can create urgency, mirror action, or subvert expectations when the reader turns the line.', difficulty:2, tags:[] },

  // ── Narrative Writing ────────────────────────────────────────────────────
  { id:'eng_105', q:'What is the primary purpose of a "story hook" at the opening of a narrative?', opts:['To summarise the entire plot upfront','To introduce all the main characters immediately','To capture the reader\'s attention and make them want to read on','To establish the historical context of the story'], ans:2, topic:'Narrative Writing', hint:'A hook grabs immediate interest — through intrigue, action, dialogue, or a surprising statement. It creates narrative tension or curiosity that compels the reader forward.', difficulty:1, tags:[] },
  { id:'eng_106', q:'A story written in first person uses which pronoun as the narrator\'s perspective?', opts:['"He" or "She"','"They"','"I"','"You"'], ans:2, topic:'Narrative Writing', hint:'First person narration uses "I" — the narrator is a character in the story. Third person uses he/she/they. Second person ("you") is rare and creates a unique direct effect.', difficulty:1, tags:[] },
  { id:'eng_107', q:'In narrative writing, what is the "denouement"?', opts:['The moment of highest tension in the story','The introduction of the main conflict','The resolution or untying of the plot after the climax','A flashback to earlier events'], ans:2, topic:'Narrative Writing', hint:'Denouement (French: "untying") is the final stage where loose ends are resolved after the climax. It brings the narrative arc to a close.', difficulty:2, tags:[] },
  { id:'eng_108', q:'Which narrative technique involves jumping back in time to reveal earlier events?', opts:['Foreshadowing','Flashback (analepsis)','Flashforward (prolepsis)','Stream of consciousness'], ans:1, topic:'Narrative Writing', hint:'A flashback (analepsis) takes the narrative backwards in time. Foreshadowing hints at the future; prolepsis jumps forward in time.', difficulty:1, tags:[] },
  { id:'eng_109', q:'What does "show, don\'t tell" mean in narrative writing?', opts:['Write only dialogue, never description','Use imagery and action to convey emotion rather than stating it directly','Always use a third-person narrator','Never reveal a character\'s thoughts'], ans:1, topic:'Narrative Writing', hint:'Instead of "she was afraid" (telling), a writer might describe trembling hands, shallow breathing, and wide eyes (showing). This creates more vivid, engaging prose.', difficulty:1, tags:[] },
  { id:'eng_110', q:'An unreliable narrator is one who:', opts:['Does not appear in the story','Has limited vocabulary','Cannot be fully trusted to give an accurate account of events','Knows everything that happens in the story'], ans:2, topic:'Narrative Writing', hint:'An unreliable narrator has biases, psychological issues, or limited knowledge that distort their account. Famous examples: Holden Caulfield in "The Catcher in the Rye", Stevens in "The Remains of the Day".', difficulty:2, tags:[] },
  { id:'eng_111', q:'Which term describes the moral or lesson that a narrative is intended to convey?', opts:['Theme','Plot','Motif','Tone'], ans:0, topic:'Narrative Writing', hint:'Theme is the central idea or message — it is what the story is really "about" beyond the surface plot. Multiple themes can coexist (e.g. friendship, loss, identity).', difficulty:1, tags:[] },
  { id:'eng_112', q:'When writing descriptively, varying sentence length is recommended primarily because:', opts:['Examiners count sentences and reward variety','It avoids using subordinate clauses','Short sentences create pace and impact; long sentences build atmosphere — varied rhythm makes writing more dynamic','Longer sentences always show better vocabulary'], ans:2, topic:'Narrative Writing', hint:'Rhythm in prose works like rhythm in music. Short punchy sentences create tension. Flowing complex sentences build scene or reflection. Alternating both keeps the reader engaged.', difficulty:2, tags:[] },
  { id:'eng_113', q:'What is a "circular narrative"?', opts:['A narrative told entirely in the present tense','A story that ends exactly or nearly where it began','A narrative with no main character','A story with three separate plotlines that never connect'], ans:1, topic:'Narrative Writing', hint:'A circular narrative begins and ends at the same point — often with the same image, line, or scene. It suggests themes of inevitability, patterns, or change (or lack of it).', difficulty:2, tags:[] },
  { id:'eng_114', q:'In descriptive writing, what does "zooming in" as a structural technique involve?', opts:['Starting with a wide overview of a setting and progressively narrowing focus to a specific detail','Describing only the central character\'s face','Using a sequence of one-word sentences','Moving rapidly between multiple locations'], ans:0, topic:'Narrative Writing', hint:'"Zoom in" mirrors a camera: start with the panoramic view (the city at dusk) → narrow to a street → a doorway → a detail (a worn brass letterbox). It draws readers into the scene.', difficulty:2, tags:[] },

  // ── Persuasive / Rhetorical Techniques ───────────────────────────────────
  { id:'eng_115', q:'The rhetorical device where a speaker/writer directly addresses an absent person or concept is called:', opts:['Anaphora','Apostrophe','Alliteration','Antithesis'], ans:1, topic:'Persuasive/Rhetorical Techniques', hint:'Rhetorical apostrophe addresses something absent — "O Death, where is thy sting?" Note: this is different from the punctuation mark apostrophe.', difficulty:3, tags:[] },
  { id:'eng_116', q:'What is the "rule of three" (tricolon) in rhetoric?', opts:['Using three paragraphs in every argument','Grouping ideas or adjectives in sets of three for persuasive effect','Asking three rhetorical questions in a row','Repeating a word three times in the same sentence'], ans:1, topic:'Persuasive/Rhetorical Techniques', hint:'Three-part lists feel natural and satisfying: "life, liberty, and the pursuit of happiness." Three items feel complete; two feel incomplete; four feel excessive. Used heavily in speeches.', difficulty:1, tags:[] },
  { id:'eng_117', q:'Which persuasive technique appeals to the audience\'s emotions rather than reason?', opts:['Logos','Ethos','Pathos','Kairos'], ans:2, topic:'Persuasive/Rhetorical Techniques', hint:'Aristotle\'s three modes of persuasion: Logos (logic/evidence), Ethos (credibility), Pathos (emotion). Kairos is timing/context — the fourth is sometimes added. Pathos moves feelings.', difficulty:2, tags:[] },
  { id:'eng_118', q:'A writer who uses statistics and expert testimony is primarily using which mode of persuasion?', opts:['Pathos','Ethos','Logos','Kairos'], ans:2, topic:'Persuasive/Rhetorical Techniques', hint:'Logos = logic, reasoning, and evidence. Statistics and expert testimony are evidence-based appeals to reason, the clearest form of logos.', difficulty:1, tags:[] },
  { id:'eng_119', q:'"As a doctor with 20 years\' experience, I can tell you that smoking kills." This is an example of:', opts:['Logos','Pathos','Ethos','Hyperbole'], ans:2, topic:'Persuasive/Rhetorical Techniques', hint:'Ethos establishes the speaker\'s authority and credibility. Claiming expertise ("as a doctor") asks the audience to trust the speaker\'s qualifications.', difficulty:1, tags:[] },
  { id:'eng_120', q:'What is a "counter-argument" in a persuasive essay, and why is it used?', opts:['An argument from the opposing side, raised and then refuted to strengthen the writer\'s position','An argument made only with emotional language','The summary paragraph at the end of an essay','A list of sources contradicting the writer\'s view'], ans:0, topic:'Persuasive/Rhetorical Techniques', hint:'Including and then dismantling opposing arguments (the "yes, but" technique) shows the writer has considered all angles. It strengthens credibility and pre-empts objections.', difficulty:2, tags:[] },
  { id:'eng_121', q:'A rhetorical question is used in persuasion primarily to:', opts:['Demand a direct answer from the audience','Make the writer appear unsure','Prompt the reader to reach the writer\'s desired conclusion without stating it directly','Ask for statistics'], ans:2, topic:'Persuasive/Rhetorical Techniques', hint:'Rhetorical questions invite the reader to think — but they are framed so the "obvious" answer supports the writer\'s point: "Who would want our children to suffer?" No answer needed.', difficulty:1, tags:[] },
  { id:'eng_122', q:'Which of the following is an example of "inclusive language" in a speech?', opts:['"You people must do better."','"I have made this decision."','"We must all take responsibility for our planet\'s future."','"The government has failed."'], ans:2, topic:'Persuasive/Rhetorical Techniques', hint:'"We" and "our" are inclusive — they unite speaker and audience around a shared goal. Inclusive language builds solidarity and makes the audience feel part of the cause.', difficulty:1, tags:[] },
  { id:'eng_123', q:'In a speech, a politician uses the phrase "Enemies of the people, agents of chaos, destroyers of hope" in quick succession. This technique is called:', opts:['Tricolon with asyndeton','Chiasmus','Polysyndeton','Litotes'], ans:0, topic:'Persuasive/Rhetorical Techniques', hint:'Three items listed without conjunctions (no "and") = tricolon + asyndeton. The lack of "and" creates speed and accumulating force — each accusation hits harder.', difficulty:3, tags:[] },
  { id:'eng_124', q:'What does it mean to write with an "authoritative tone" in non-fiction?', opts:['Using complicated jargon to confuse readers','Presenting opinions as absolute facts aggressively','Using confident, assured language that demonstrates knowledge and expertise','Writing only in passive voice'], ans:2, topic:'Persuasive/Rhetorical Techniques', hint:'Authoritative tone conveys confidence and expertise without aggression. It is established through precise vocabulary, evidence, and declarative statements rather than hedging.', difficulty:2, tags:[] },

  // ── Grammar & Punctuation ────────────────────────────────────────────────
  { id:'eng_125', q:'Which sentence uses a semicolon correctly?', opts:['The dog ran quickly; because it was scared.','She loves reading; her bookshelf is enormous.','I want; to go home.','He ate; the whole meal.'], ans:1, topic:'Grammar & Punctuation', hint:'A semicolon links two independent clauses of equal weight without a conjunction. "Because" makes a dependent clause — wrong. "She loves reading" and "her bookshelf is enormous" are both complete clauses.', difficulty:2, tags:[] },
  { id:'eng_126', q:'In the sentence "The teacher, who had been marking all night, fell asleep," the commas serve to:', opts:['Mark a list of adjectives','Separate an independent clause from the main sentence','Enclose a non-defining (non-restrictive) relative clause','Indicate direct speech'], ans:2, topic:'Grammar & Punctuation', hint:'A non-defining (non-restrictive) relative clause adds extra information that could be removed without changing the core meaning. The commas signal this — remove the clause and the sentence still works.', difficulty:2, tags:[] },
  { id:'eng_127', q:'What is the difference between "its" and "it\'s"?', opts:['"its" is plural; "it\'s" is singular','"it\'s" is a contraction of "it is/has"; "its" is the possessive pronoun','They are interchangeable','"its" is formal; "it\'s" is informal'], ans:1, topic:'Grammar & Punctuation', hint:'"It\'s" = "it is" or "it has" (apostrophe marks the omission). "Its" = possessive (like "his" or "her") — and possessive pronouns NEVER take apostrophes in standard English.', difficulty:1, tags:[] },
  { id:'eng_128', q:'Identify the error: "There are less students in the hall than yesterday."', opts:['No error','Should be "fewer students" — "fewer" for countable nouns, "less" for uncountable','Should be "less peoples"','Should be "lesser students"'], ans:1, topic:'Grammar & Punctuation', hint:'"Fewer" is used with countable nouns (students, apples, people). "Less" is used with uncountable nouns (water, time, patience). Students are countable: "fewer students."', difficulty:2, tags:[] },
  { id:'eng_129', q:'Which of the following is a complex sentence?', opts:['The cat sat on the mat.','It rained and the road flooded.','Although it rained heavily, the match continued.','Run! Stop! Listen!'], ans:2, topic:'Grammar & Punctuation', hint:'A complex sentence has a main clause and at least one subordinate clause. "Although it rained heavily" is a subordinate clause; "the match continued" is the main clause.', difficulty:1, tags:[] },
  { id:'eng_130', q:'What grammatical term describes "quickly" in the sentence "She ran quickly"?', opts:['Adjective','Noun','Adverb','Pronoun'], ans:2, topic:'Grammar & Punctuation', hint:'Adverbs modify verbs, adjectives, or other adverbs. "Quickly" modifies the verb "ran" — telling us how she ran.', difficulty:1, tags:[] },
  { id:'eng_131', q:'Which of the following contains a dangling modifier?', opts:['Having finished the exam, she left the hall.','Having finished the exam, the hall was left by her.','After studying all night, Maria felt prepared.','Running late, he hailed a taxi.'], ans:1, topic:'Grammar & Punctuation', hint:'A dangling modifier doesn\'t clearly attach to the noun it modifies. "Having finished the exam" suggests the hall finished the exam — not she. The modifier is left "dangling" without its subject.', difficulty:3, tags:[] },
  { id:'eng_132', q:'Which sentence is written in passive voice?', opts:['The chef prepared a delicious meal.','The children laughed loudly.','Mistakes were made by the committee.','She finished the project on time.'], ans:2, topic:'Grammar & Punctuation', hint:'Passive voice: the subject receives the action (Mistakes were made). Active voice: the subject performs the action (The committee made mistakes). Passive can obscure responsibility.', difficulty:2, tags:[] },
  { id:'eng_133', q:'Which correctly uses a colon?', opts:['He loves: football, tennis and golf.','He loves football: tennis and golf.','He has one ambition: to win the championship.','He: loves football tennis and golf.'], ans:2, topic:'Grammar & Punctuation', hint:'A colon introduces something that follows directly from the main clause — a list, explanation, or elaboration. "He has one ambition" is a complete clause; the colon then introduces what it is.', difficulty:2, tags:[] },
  { id:'eng_134', q:'A compound sentence contains:', opts:['One main clause and one subordinate clause','Two or more independent clauses joined by a coordinating conjunction','Only one independent clause','A relative clause modifying the main clause'], ans:1, topic:'Grammar & Punctuation', hint:'Compound = two independent clauses joined by FANBOYS (For, And, Nor, But, Or, Yet, So). "She studied hard, and she passed the exam."', difficulty:1, tags:[] },

  // ── Vocabulary & Word Choice ─────────────────────────────────────────────
  { id:'eng_135', q:'What is the "connotation" of a word?', opts:['Its dictionary definition','The emotional associations and implications it carries beyond its literal meaning','Its pronunciation in formal speech','The number of syllables it contains'], ans:1, topic:'Vocabulary & Word Choice', hint:'Connotation vs denotation: "home" and "house" have the same denotation (a building to live in) but different connotations — "home" carries warmth, belonging, and memory.', difficulty:1, tags:[] },
  { id:'eng_136', q:'Which word has a positive connotation among: "slim," "thin," "scrawny," "gaunt"?', opts:['Thin','Scrawny','Slim','Gaunt'], ans:2, topic:'Vocabulary & Word Choice', hint:'"Slim" suggests attractively slender. "Scrawny" and "gaunt" imply unhealthily thin (negative). "Thin" is neutral. Writers carefully choose words for their connotative charge.', difficulty:1, tags:[] },
  { id:'eng_137', q:'What is the effect of using the word "slithered" rather than "moved" to describe a snake?', opts:['It is shorter and more efficient','It creates a visual image through onomatopoeia, suggesting stealth and unease','It is less vivid but more accurate','It reveals the narrator dislikes snakes'], ans:1, topic:'Vocabulary & Word Choice', hint:'"Slithered" is both onomatopoeic (sounds like sliding) and carries negative connotations of snakes, deceit, and unease. Precise verb choice elevates writing enormously.', difficulty:2, tags:[] },
  { id:'eng_138', q:'A writer uses the word "domicile" instead of "house." What is the effect?', opts:['Creates a more emotional connection','Sounds formal and bureaucratic, creating distance','Makes the text easier to read','Has no effect on meaning or tone'], ans:1, topic:'Vocabulary & Word Choice', hint:'"Domicile" is a formal, legal register word. Choosing it over "house" or "home" creates a cold, bureaucratic tone — detaching the reader emotionally.', difficulty:2, tags:[] },
  { id:'eng_139', q:'What is a "semantic field"?', opts:['A grammar rule about sentence structure','A group of words related to the same theme or subject area','A type of metaphor using natural imagery','A list of synonyms for a word'], ans:1, topic:'Vocabulary & Word Choice', hint:'A semantic field is a cluster of words sharing a topic — e.g., "grave, coffin, shroud, mourning, epitaph" all belong to the semantic field of death. Writers build semantic fields to reinforce themes.', difficulty:2, tags:[] },
  { id:'eng_140', q:'Which word best replaces "said" in this sentence to convey anger: "\'Get out!\' she ___ at him."?', opts:['whispered','murmured','snarled','cooed'], ans:2, topic:'Vocabulary & Word Choice', hint:'Snarled conveys aggressive anger. Murmured and whispered suggest softness; cooed suggests affection. Precise dialogue tags reveal emotion without stating it.', difficulty:1, tags:[] },
  { id:'eng_141', q:'What is the difference between "denotation" and "connotation"?', opts:['They are the same thing','Denotation is literal dictionary meaning; connotation is associated emotional meaning','Denotation is emotional; connotation is literal','Denotation refers to verbs; connotation refers to nouns'], ans:1, topic:'Vocabulary & Word Choice', hint:'Key distinction for English exams: denotation = what a word literally means; connotation = what it implies or feels like. "Skinny" and "slender" denote the same thing but connote different things.', difficulty:1, tags:[] },
  { id:'eng_142', q:'Which sentence uses a more formal register?', opts:['The company\'s been doing really well lately.','The organisation has demonstrated significant financial growth in the preceding quarter.','Things are going great for the firm right now.','The business is absolutely smashing it.'], ans:1, topic:'Vocabulary & Word Choice', hint:'Formal register: complex nouns ("organisation", "growth"), precise time references ("preceding quarter"), no contractions. Informal: contractions, colloquialisms ("smashing it", "really well").', difficulty:1, tags:[] },
  { id:'eng_143', q:'What is the term for a mild or indirect expression used in place of a harsh or unpleasant one?', opts:['Hyperbole','Oxymoron','Euphemism','Litotes'], ans:2, topic:'Vocabulary & Word Choice', hint:'A euphemism softens unpleasant realities — "passed away" for "died", "let go" for "fired." Writers and politicians use them to avoid directness. Litotes = understatement using negatives.', difficulty:1, tags:[] },
  { id:'eng_144', q:'In a poem, the word "crimson" is used rather than "red." What might this suggest?', opts:['No difference — they mean exactly the same thing','Crimson suggests deeper, richer, possibly darker or more ominous red — adding emotional and visual intensity','Crimson is always positive and celebratory','Red would have been too formal for a poem'], ans:1, topic:'Vocabulary & Word Choice', hint:'Crimson carries connotations of deep richness, passion, blood, and intensity. "Red" is plainer. Word choice in poetry is deliberate — every word is chosen for both meaning and sound.', difficulty:2, tags:[] },

  // ── Text Structure & Form ────────────────────────────────────────────────
  { id:'eng_145', q:'What is the purpose of a subheading in a non-fiction article?', opts:['To conclude the writer\'s argument','To break up text into sections and help the reader navigate the article','To introduce characters','To provide statistical evidence'], ans:1, topic:'Text Structure & Form', hint:'Subheadings organise text, signal topic shifts, and help readers navigate to relevant sections. They are structural features of non-fiction (articles, reports, leaflets).', difficulty:1, tags:[] },
  { id:'eng_146', q:'A sonnet traditionally contains how many lines?', opts:['8','10','14','16'], ans:2, topic:'Text Structure & Form', hint:'A sonnet has 14 lines. The Petrarchan form is split 8 + 6 (octave + sestet); the Shakespearean form is 3 quatrains + a couplet. The final couplet often contains the turn or resolution.', difficulty:1, tags:[] },
  { id:'eng_147', q:'What is the "volta" in a sonnet?', opts:['The rhyme scheme of the octave','A turn or shift in argument or perspective, usually between the octave and sestet','The final rhyming couplet','The repetition of a key phrase'], ans:1, topic:'Text Structure & Form', hint:'Volta (Italian: "turn") is the pivot — the moment the argument or emotional direction shifts. In a Petrarchan sonnet it typically occurs at the sestet (line 9); in Shakespearean at the couplet.', difficulty:2, tags:[] },
  { id:'eng_148', q:'Which structural technique involves repeating the opening line/image of a text at its close?', opts:['In medias res','Circular structure','Foreshadowing','Stream of consciousness'], ans:1, topic:'Text Structure & Form', hint:'Circular structure begins and ends at the same point. It suggests themes of inevitability, memory, or the passage of time — and is a strong structural device in both poetry and prose.', difficulty:1, tags:[] },
  { id:'eng_149', q:'When a narrative begins "in the middle of the action" without background context, this is called:', opts:['Flashback','Denouement','In medias res','Exposition'], ans:2, topic:'Text Structure & Form', hint:'"In medias res" (Latin: in the middle of things) plunges readers directly into action, creating immediate engagement. Background is revealed later through flashback or dialogue.', difficulty:2, tags:[] },
  { id:'eng_150', q:'A ballad is a type of poem that typically:', opts:['Has no rhyme scheme and free verse','Tells a story, often with a regular rhythm and rhyme scheme, and sometimes a refrain','Is always a love poem','Must be 14 lines long'], ans:1, topic:'Text Structure & Form', hint:'Ballads are narrative poems — they tell stories (often tragic or dramatic). They traditionally use ABAB or ABCB rhyme schemes and regular metre. Folk ballads often have a repeated refrain.', difficulty:1, tags:[] },
  { id:'eng_151', q:'In non-fiction, what does "mode" refer to?', opts:['The topic of the text','The intended audience of the text','Whether the text is written, spoken, or multimodal (combining text, image, sound)','The length of the text'], ans:2, topic:'Text Structure & Form', hint:'Mode describes the channel: written text, spoken word, or multimodal (e.g. a webpage combines written text, images, video). Understanding mode helps analyse how form shapes meaning.', difficulty:2, tags:[] },
  { id:'eng_152', q:'Which feature would you expect in a formal report but NOT in a personal letter?', opts:['First-person pronouns','Headings and subheadings to organise sections','Conversational asides','An informal sign-off'], ans:1, topic:'Text Structure & Form', hint:'Formal reports use structural features: executive summary, numbered sections, headings. Personal letters are discursive, personal in register, and use informal organisation.', difficulty:1, tags:[] },
  { id:'eng_153', q:'Free verse poetry is characterised by:', opts:['A strict iambic pentameter throughout','Exactly 14 lines','No fixed rhyme scheme or regular metre','Always having a refrain'], ans:2, topic:'Text Structure & Form', hint:'Free verse (vers libre) abandons traditional formal constraints — no set metre, no fixed rhyme scheme. This allows form to reflect content freely. Walt Whitman and Carol Ann Duffy use it extensively.', difficulty:1, tags:[] },
  { id:'eng_154', q:'What is the effect of a writer opening a persuasive essay with a shocking statistic?', opts:['Establishes ethos immediately','Confuses the reader with numbers','Immediately engages the reader with credible evidence and creates urgency','Shows the writer lacks confidence in their argument'], ans:2, topic:'Text Structure & Form', hint:'A shocking statistic (e.g. "Every 40 seconds, someone dies by suicide") immediately impacts the reader emotionally (pathos) while providing evidence (logos). It establishes stakes from the first line.', difficulty:2, tags:[] },

  // ── Context & Interpretation ─────────────────────────────────────────────
  { id:'eng_155', q:'Why is biographical context important when interpreting a poem?', opts:['It proves what the poem "really means"','It can offer insight into a writer\'s possible intentions, but the text should remain central','The biography overrides all other interpretations','Biographical context is irrelevant to English exams'], ans:1, topic:'Context & Interpretation', hint:'Context informs interpretation — knowing Owen fought in WWI enriches our reading of Dulce et Decorum Est. But it doesn\'t dictate meaning — the text must provide evidence for any claim.', difficulty:2, tags:[] },
  { id:'eng_156', q:'What does "historical context" help a reader understand about a text?', opts:['The grammatical rules the writer followed','The social, political, or cultural conditions that influenced the writer and their work','Only the date the text was written','Whether the text is fiction or non-fiction'], ans:1, topic:'Context & Interpretation', hint:'Historical context includes the era\'s social attitudes, political events, and cultural norms. Understanding Victorian attitudes to women illuminates much of Dickens or Hardy.', difficulty:1, tags:[] },
  { id:'eng_157', q:'Which of the following is an example of a valid "alternative interpretation" of a text?', opts:['A reading that ignores all textual evidence','A reading based entirely on what a student personally prefers','A Marxist reading of "Oliver Twist" that focuses on class exploitation','A reading that misquotes the text'], ans:2, topic:'Context & Interpretation', hint:'A literary theory (Marxist, feminist, post-colonial) provides a lens through which to re-read a text. Such readings are valid if supported by textual evidence — they reveal different layers of meaning.', difficulty:2, tags:[] },
  { id:'eng_158', q:'What is meant by "the implied audience" of a text?', opts:['The number of people who read the text','The readership the writer appears to be writing for, based on textual evidence','The people the writer explicitly addresses in the title','The editor who approved the text for publication'], ans:1, topic:'Context & Interpretation', hint:'Writers shape texts for an intended audience. Language, register, assumed knowledge, and cultural references all reveal who the writer is "writing for" — even if not explicitly stated.', difficulty:2, tags:[] },
  { id:'eng_159', q:'A feminist reading of "Jane Eyre" would most likely focus on:', opts:['The religious imagery in the novel','How Charlotte Brontë challenges the constraints placed on women in Victorian society','The historical accuracy of Victorian education','The reliability of the first-person narrator'], ans:1, topic:'Context & Interpretation', hint:'Feminist criticism examines how texts represent gender. Jane Eyre\'s rebellion against male authority (Rochester, St John) and her insistence on equality make it rich territory for a feminist reading.', difficulty:2, tags:[] },
  { id:'eng_160', q:'Why must textual evidence always be used when making an analytical point in an exam?', opts:['Examiners require quotations in every sentence','Evidence links the claim to the text — without it, a point is only an assertion, not an analysis','Personal opinion is always more persuasive than evidence','Quotations replace the need for any explanation'], ans:1, topic:'Context & Interpretation', hint:'The "point, evidence, explanation" (PEE/PEEL/PETAL) structure ensures claims are grounded. Without evidence, the reader cannot verify the claim. Without explanation, the evidence is unexplored.', difficulty:1, tags:[] },
  { id:'eng_161', q:'In analysing a text, what does the term "authorial intent" mean, and why must it be used cautiously?', opts:['It refers to the plot of the story; it must be used carefully to avoid spoilers','It means what the writer intended; it is cautious because we cannot know intent with certainty and should focus on textual effects','It is the reader\'s interpretation; it should match the author\'s exactly','It refers to the publisher\'s decisions; caution because publishers change meaning'], ans:1, topic:'Context & Interpretation', hint:'"The writer intended..." is a claim about motivation. We can infer likely intentions from context and effect — but since we cannot interview dead authors, focus on what the text does to the reader.', difficulty:2, tags:[] },
  { id:'eng_162', q:'Which statement about reading non-fiction texts is correct?', opts:['Non-fiction texts always present the truth','Writers of non-fiction always use logical evidence only','Non-fiction can still employ bias, persuasion, and selective presentation of facts','Non-fiction texts have no literary techniques'], ans:2, topic:'Context & Interpretation', hint:'Non-fiction = based on real events/facts — but it can still be biased, subjective, and rhetorically crafted. Opinion columns, memoirs, and journalism all shape "facts" through selection and language.', difficulty:1, tags:[] },
  { id:'eng_163', q:'What is the significance of setting in a literary text?', opts:['Setting only matters in travel writing','Setting establishes realism but has no symbolic function','Setting creates atmosphere, can reflect character psychology, and often symbolises themes','Setting is irrelevant to character or theme'], ans:2, topic:'Context & Interpretation', hint:'Setting is a rich literary tool: the moors in "Wuthering Heights" mirror Catherine\'s wild nature; the fog in Dickens mirrors moral ambiguity. Place is never merely backdrop in skilled writing.', difficulty:2, tags:[] },
  { id:'eng_164', q:'A student writes: "The writer uses a metaphor which is effective." What is the weakness of this analysis?', opts:['The student has identified the technique correctly','The student has described technique but failed to explain its effect on the reader in specific terms','The student should never mention metaphors','The student should have used a quotation from a different part of the text'], ans:1, topic:'Context & Interpretation', hint:'"Effective" is vague — it tells the examiner nothing. Strong analysis specifies the effect: "the metaphor of \'iron chains\' suggests the character\'s complete loss of freedom, evoking sympathy." Be precise.', difficulty:2, tags:[] },
]
